class FETextBase
{
public:
	virtual ~FETextBase();
};

class TextPadding
{
	char padding[76];
};

class PreformatText : public TextPadding, public FETextBase {};
class TextString : public TextPadding, public FETextBase {};
class BoxText : public TextPadding, public FETextBase {};

class FEMultiMenu
{
	char padding[352];

public:
	virtual ~FEMultiMenu();
};

enum { SURFER_LAST = 14 };

class SurferBioFrontEnd : public FEMultiMenu
{
	PreformatText* bios[SURFER_LAST];
	void* sys;
	void* bio_parent;
	TextString* firstname;
	TextString* lastname;
	BoxText* intro;

public:
	virtual ~SurferBioFrontEnd();
};

SurferBioFrontEnd::~SurferBioFrontEnd()
{
	for(int i=0; i<SURFER_LAST; i++)
		delete bios[i];
	delete firstname;
	delete lastname;
	delete intro;
}
